<template><v-row justify="center"><v-col cols="12" sm="8" md="5"><v-card class="pa-6"><h1 class="text-h4 mb-5">Restablecer contraseña</h1><AppAlert :message="message" :type="type" @clear="message=''"/><v-form v-model="valid" @submit.prevent="submit"><PasswordFields v-model="password" label="Nueva contraseña"/><v-btn block color="primary" type="submit" :disabled="!valid" :loading="loading">Actualizar contraseña</v-btn></v-form></v-card></v-col></v-row></template>
<script setup>import{ref}from'vue';import{useRoute,useRouter}from'vue-router';import api from'../services/api';import AppAlert from'../components/AppAlert.vue';import PasswordFields from'../components/PasswordFields.vue';const route=useRoute(),router=useRouter(),password=ref(''),valid=ref(false),loading=ref(false),message=ref(''),type=ref('error');async function submit(){loading.value=true;try{await api.post('/auth/reset-password',{token:route.query.token,new_password:password.value});router.push('/ingresar')}catch(e){message.value=e.response?.data?.detail||'No fue posible actualizar la contraseña'}finally{loading.value=false}}</script>
